1	/**
2	 * The landing page's only entry point into the phone demo.
3	 *
4	 * Everything the page needs to know lives here, so wiring the demo in is a
5	 * one-line swap for the dead <iframe> rather than a second pass over
6	 * landing-page.tsx. This module is deliberately tiny and imports nothing from
7	 * the demo chunk — scenes, primitives and CSS all arrive behind the lazy
8	 * boundary below, which is what keeps a visitor who never scrolls to the story
9	 * from downloading them (§6 rules 1–3).
10	 *
11	 * Failure modes are covered by construction, because a blank phone is the bug
12	 * this whole plan exists to fix (§7.1):
13	 *   • chunk still loading → static shell
14	 *   • chunk failed to load → static shell
15	 *   • scene threw while rendering → static shell
16	 *   • no IntersectionObserver → load immediately
17	 *   • Save-Data → no prefetch, and finished frames when it does load
18	 */
19	import { Component, Suspense, lazy, useCallback, useEffect, useState, type ReactNode } from 'react';
20	import { SCREEN_H, SCREEN_W } from './tokens';
21	import type { LandingPhoneScene, LandingPhoneState } from './types';
22	import { useApproaching, useStillPreference, useStoryProgress } from './useStoryProgress';
23	
24	const PhoneStage = lazy(() => import('./LandingPhoneDemo'));
25	
26	/**
27	 * Inline-styled on purpose: the shell is the pre-chunk state, so it must not
28	 * depend on landing-phone.css. It is a few hundred bytes and carries the
29	 * phone's silhouette, not its content.
30	 */
31	function StaticShell({ scale = 1, rotateY = 0, label = 'taptpay app' }: { scale?: number; rotateY?: number; label?: string }) {
32	  return (
33	    <div
34	      role="img"
35	      aria-label={label}
36	      data-demo-scene="shell"
37	      style={{
38	        width: SCREEN_W * scale,
39	        height: SCREEN_H * scale,
40	        borderRadius: 54 * scale,
41	        background: 'linear-gradient(158deg,#0a1656 0%,#040D6D 46%,#0b1a6e 100%)',
42	        boxShadow: '0 40px 120px rgba(4,13,109,0.55), inset 0 0 0 2px rgba(185,203,232,0.35)',
43	        transform: `perspective(2200px) rotateY(${rotateY}deg)`,
44	      }}
45	    />
46	  );
47	}
48	
49	class PhoneBoundary extends Component<{ fallback: ReactNode; children: ReactNode }, { failed: boolean }> {
50	  state = { failed: false };
51	
52	  static getDerivedStateFromError() {
53	    return { failed: true };
54	  }
55	
56	  componentDidCatch(error: unknown) {
57	    // The landing page is marketing, not a workflow: degrade to the shell and
58	    // leave a breadcrumb rather than taking the section down.
59	    if (import.meta.env?.DEV) console.error('[landing-phone] scene failed', error);
60	  }
61	
62	  render() {
63	    return this.state.failed ? this.props.fallback : this.props.children;
64	  }
65	}
66	
67	export type LandingPhoneMountProps = {
68	  /**
69	   * cinematic — scroll drives scene and step across the eight story zones.
70	   * industries — the tab picks the scene; step is driven by the tab's own
71	   * progress or pinned to the finished frame.
72	   */
73	  variant: 'cinematic' | 'industries';
74	  /** Industries only: which scene the selected tab shows. */
75	  scene?: LandingPhoneScene;
76	  /** Industries only: pin to an explicit milestone (e.g. replay controls). */
77	  state?: LandingPhoneState;
78	  scale?: number;
79	  /** Degrees of Y rotation at progress 0 and 1; the phone turns between them. */
80	  spin?: [number, number];
81	  /**
82	   * Industries only: "try it live" — tap-through and replay (§3.3). This is
83	   * local milestone stepping, never live production behaviour.
84	   */
85	  interactive?: boolean;
86	  /** Milestone count for the selected scene; supplied by the caller so the
87	   *  main chunk never imports the registry to find out. */
88	  steps?: number;
89	  className?: string;
90	};
91	
92	export function LandingPhoneMount({
93	  variant, scene, state, scale = 1, spin = [-18, 18], interactive = false, steps, className,
94	}: LandingPhoneMountProps) {
95	  const [ref, near] = useApproaching<HTMLDivElement>('600px');
96	  const { reducedMotion, saveData } = useStillPreference();
97	  const progress = useStoryProgress(ref, near && variant === 'cinematic');
98	
99	  // Tap-through state for the Industries phone. Selecting a different tab
100	  // restarts that workflow from its own first milestone.
101	  const [step, setStep] = useState(0);
102	  useEffect(() => setStep(0), [scene]);
103	  const advance = useCallback(() => {
104	    setStep((s) => (steps && steps > 0 ? (s + 1) % steps : s + 1));
105	  }, [steps]);
106	
107	  const still = reducedMotion || saveData;
108	  // Save-Data viewers get the shell until the story is actually in view, not
109	  // merely approaching, so the chunk is never speculatively fetched for them.
110	  const load = saveData ? near && progress > 0 : near;
111	  const rotateY = variant === 'cinematic' ? spin[0] + (spin[1] - spin[0]) * progress : 0;
112	
