3	 *
4	 * Everything in this module is pure data — no React runtime, no DOM, no Date.
5	 * The scroll controller, the scene modules and the tests all compile against
6	 * these types, which is what lets the three vertical lanes be built and
7	 * verified independently of each other.
8	 */
9	import type { ComponentType } from 'react';
10	
11	/** One scene per landing story zone: intro + cards 01–07. */
12	export type LandingPhoneScene =
13	  | 'overview'
14	  | 'rent-weekly'
15	  | 'property-bill'
16	  | 'trades-invoice'
17	  | 'quote-deposit'
18	  | 'retail-sale'
19	  | 'retail-split'
20	  | 'checkout-wallet';
